// --- REFERENCE base-utils repo

import {
	pass, undef, defined, notdefined,
	assert, obviously, croak, words,
	} from 'base'
import {getPrefix} from 'unicode'
import {
	LOG, stringFits, clearLog, getLog, logWidth,
	} from 'logger'
import {
	jsType, hash, isArrayOfStrings, integer, isString,
	isFunction, isArray, isInteger, nonEmpty, isObject,
	} from 'datatypes'
import {
	blockToArray, arrayToBlock, getOptions, spaces, tabs,
	} from 'llutils'
import {OL, ML, toNice} from 'nice'
import {parsePath} from 'fsys'
import {CCallStack} from 'trace-stack'

// ---------------------------------------------------------------------------

export const stack = new CCallStack()

type TFuncDesc = {
	funcName: string
	plus: boolean
	}

// --- Comes from call to doTrace()
let lFuncList: TFuncDesc[] = []

let internalDebugging = false

type TLogFuncMult = (
	level: number,
	funcName: string,
	lValues: unknown[]
	) => void

type TLogFuncOne = (
	level: number,
	funcName: string,
	lValues: unknown
	) => void

type TLogFuncNone = (
	level: number,
	funcName: string,
	) => void

type TLogFunc = TLogFuncMult | TLogFuncOne | TLogFuncNone

// --- Loggers
let logEnter:  TLogFuncMult
let logReturn: TLogFuncOne
let logYield:  TLogFuncOne
let logResume: TLogFuncNone
let logValue:  TLogFuncOne

let traceAll = false   // --- if true, always log
let traceNone = false  // --- if true, never log

// ---------------------------------------------------------------------------

export const doTrace = (
		traceWhat: boolean | string | string[]
		): void => {

	// --- traceWhat can be:
	//        1. a boolean (false = disable, true = debug all)
	//        2. a string (name of a function)
	//        3. an array of strings (names of functions)

	if (internalDebugging) {
		console.log(`doTrace ${OL(traceWhat)}`)
	}

	resetTracing()

	// --- process traceWhat
	switch(jsType(traceWhat)) {
		case 'boolean': {
			if (traceWhat) {
				if (internalDebugging) {
					console.log("set traceAll")
				}
				traceAll = true
			}
			else {
				if (internalDebugging) {
					console.log("set traceNone")
				}
				traceNone = true
			};break;
		}
		case 'string':case 'array': {
			if (internalDebugging) {
				console.log(`traceWhat is ${OL(traceWhat)}`)
			}
			obviously((typeof traceWhat === 'string') || isArray(traceWhat))
			lFuncList = getFuncList(traceWhat);break;
		}
		default: {
			croak(`Bad arg 1: ${OL(traceWhat)}`)
		}
	}

	if (internalDebugging) {
		dumpFuncList()
	}
	return
}

// ---------------------------------------------------------------------------

export const resetTracing = () => {

	// --- reset everything
	stack.reset()
	lFuncList = []
	traceAll = false
	traceNone = false
	logEnter  = stdEnter
	logReturn = stdReturn
	logYield  = stdYield
	logResume = stdResume
	logValue  = stdLogValue
	clearLog()
	return
}

// ---------------------------------------------------------------------------
//  EXPAND THESE
// ---------------------------------------------------------------------------

export const setEnterLogger = (
		type: string,
		func: TLogFuncMult
		): void => {

	if (internalDebugging) {
		console.log("set custom enter logger")
	}
	logEnter = func
	return
}

// ---------------------------------------------------------------------------

export const getFuncList = (
		funcs: string | string[]
		): TFuncDesc[] => {

	const lFuncs: TFuncDesc[] = []    // return value

	// --- Allow passing in an array of strings
	if (isArray(funcs)) {
		for (const str of funcs) {
			const lItems = getFuncList(str)   // recursive call
			lFuncs.push(...lItems)
		}
	}
	else {
		for (const word of words(funcs)) {
			const [funcName, modifier] = parseFuncStr(word)
			assert(defined(funcName), `Bad debug object: ${OL(word)}`)
			lFuncs.push({
				funcName,
				plus: (modifier === '+')
				})
		}
	}
	return lFuncs
}

// ---------------------------------------------------------------------------
// Stack is only modified in these 8 functions (it is reset in doTrace())
// ---------------------------------------------------------------------------

export const trEnter = (
		funcName: string,
		lValues: unknown[] = []
		): boolean => {

	const doTrace = isTracingFunc(funcName)
	if (internalDebugging) {
		if (defined(lValues)) {
			console.log(`trEnter ${OL(funcName)}, ${OL(lValues)}`)
		}
		else {
			console.log(`trEnter ${OL(funcName)}`)
		}
		console.log(`   - doTrace = ${OL(doTrace)}`)
	}

	if (doTrace) {
		const level = stack.logLevel
		logEnter(level, funcName, lValues)
	}

	stack.enter(funcName, lValues, doTrace)
	return true
}

// ---------------------------------------------------------------------------

export const trReturn = (
		funcName: string,
		val: (unknown | undefined) = undef
		): boolean => {

	assert((funcName === stack.curFuncName),
		`trReturn(${funcName}) but cur func is ${stack.curFuncName}`)
	const doTrace = isTracingFunc(funcName)
	if (internalDebugging) {
		console.log(`trReturn ${OL(funcName)}`)
		console.log(`   - doTrace = ${OL(doTrace)}`)
	}
	if (doTrace) {
		const level = stack.logLevel
		logReturn(level, funcName, val)
	}

	stack.returnFrom(funcName, val)
	return true
}

// ---------------------------------------------------------------------------

export const trYield = (
		funcName: string,
		val: (unknown | undefined)
		): boolean => {

	const doTrace = isTracingFunc(funcName)
	if (internalDebugging) {
		console.log(`trYield ${OL(funcName)} ${OL(val)}`)
		console.log(`   - doTrace = ${OL(doTrace)}`)
	}
	if (doTrace) {
		const level = stack.logLevel
		logYield(level, funcName, val)
	}

	stack.yieldFrom(funcName, val)
	return true
}

// ---------------------------------------------------------------------------

export const trResume = (
		funcName: string
		): boolean => {

	const doTrace = isTracingFunc(funcName)
	if (internalDebugging) {
		console.log(`trResume ${OL(funcName)}`)
		console.log(`   - doTrace = ${OL(doTrace)}`)
	}
	if (doTrace) {
		const level = stack.logLevel
		logResume(level-1, funcName)
	}
	stack.resume(funcName)
	return true
}

// ---------------------------------------------------------------------------

export const tr = (
		label: string,
		val: unknown
		): boolean => {

	const doTrace = isTracingFunc(stack.curFuncName)
	if (internalDebugging) {
		console.log(`tr ${OL(label)}, ${OL(val)}`)
		console.log(`   - doTrace = ${OL(doTrace)}`)
	}
	if (doTrace) {
		const level = stack.logLevel
		logValue(level, label, val)
	}
	return true
}

// ---------------------------------------------------------------------------

export const isTracingFunc = (
		funcName: string
		): boolean => {

	if (traceNone) {
		return false
	}
	if (traceAll) {
		return true
	}

	// --- funcName came from a call to trEnter()
	//     it might be of form <object>.<method>
	// --- We KNOW that funcName is active!

	if (internalDebugging) {
		console.log(`isTracingFunc(${OL(funcName)})`)
		console.log(lFuncList)
		stack.dump()
	}

	const lParts = funcName.split('.')

	for (const h of lFuncList) {
		if (h.funcName === funcName) {
			if (internalDebugging) {
				console.log(`   - TRUE - ${OL(funcName)} is in lFuncList`)
			}
			return true
		}
		if (h.plus && stack.isActive(h.funcName)) {
			if (internalDebugging) {
				console.log(`   - TRUE - ${OL(h.funcName)} is active`)
			}
			return true
		}
	}

	if (lParts.length === 2) {   // --- came from trEnter()
		const methodName = lParts[1]
		for (const h of lFuncList) {
			if (h.funcName === methodName) {
				if (internalDebugging) {
					console.log(`   - TRUE - ${OL(methodName)} is in lFuncList`)
				}
				return true
			}
		}
	}
	if (internalDebugging) {
		console.log("   - FALSE")
	}
	return false
}

// ---------------------------------------------------------------------------
// ---------------------------------------------------------------------------
//    Only these 8 functions ever call LOG or LOGVALUE

export const stdEnter: TLogFuncMult = (
		level: integer,
		funcName: string,
		lArgs: unknown[]
		): void => {

	const labelPre = getPrefix(level, 'plain')
	if (lArgs.length === 0) {
		LOG(labelPre + `enter ${funcName}`)
	}
	else {
		const str = `enter ${funcName} ${OL(lArgs)}`
		if (stringFits(`${labelPre}${str}`)) {
			LOG(labelPre + str)
		}
		else {
			LOG(labelPre + `enter ${funcName}`)
			let i1 = 0;for (const arg of lArgs) {const i = i1++;
				LOGVALUE(`arg[${i}]`, arg, {
						prefix: getPrefix(level+1, 'plain'),
						itemPrefix: getPrefix(level+2, 'noLastVbar'),
						short: false
						})
			}
		}
	}
	return
}

// ---------------------------------------------------------------------------

export const stdReturn: TLogFuncOne = (
		level: integer,
		funcName: string,
		val: unknown
		): void => {

	const labelPre = getPrefix(level, 'withArrow')
	const str = `return ${OL(val)} from ${funcName}`
	if (stringFits(str)) {
		LOG(labelPre + str)
	}
	else {
		LOG(labelPre + `return from ${funcName}`)
		LOGVALUE("val", val, {
			prefix: getPrefix(level, 'noLastVbar'),
			itemPrefix: getPrefix(level, 'noLastVbar'),
			short: false
			})
	}
	return
}

// ---------------------------------------------------------------------------

export const stdYield: TLogFuncOne = (
		level: integer,
		funcName: string,
		val: unknown
		): void => {

	const labelPre = getPrefix(level, 'withYield')
	const str = `yield from ${funcName}: ${OL(val)}`
	if (stringFits(str)) {
		LOG(labelPre + str)
	}
	else {
		LOGVALUE('', val, {
			prefix: getPrefix(level, 'plain'),
			itemPrefix: getPrefix(level, 'plain')
			})
	}
	return
}

// ---------------------------------------------------------------------------

export const stdResume: TLogFuncNone = (
		level: integer,
		funcName: string,
		): void => {

	assert(isInteger(level), "level not an integer")
	const labelPre = getPrefix(level+1, 'withResume')
	LOG(labelPre + "resume")
	return
}

// ---------------------------------------------------------------------------

export const stdLogValue: TLogFuncOne = (
		level: integer,
		label: string,
		val: unknown
		): void => {

	assert(isInteger(level), "level not an integer")

	LOGVALUE(label, val, {
		prefix: getPrefix(level, 'plain')
		})
	return
}

// ---------------------------------------------------------------------------
// ........................................................................

export const parseFuncStr = (str: string): [string, string] => {
	// --- returns [fullName, modifier]

	const lMatches = str.match(/^([A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)?)(\+)?$/)
	assert(defined(lMatches), "Bad func desc: ${OL(str)}")
	const [_, fullName, modifier] = lMatches
	return [fullName, modifier]
}

