export const debugTracing = (debugFlag = true): void => {

	internalDebugging = debugFlag
	if (debugFlag) {
		console.log("turn on internal debugging in debug.coffee")
	}
	else {
		console.log("turn off internal debugging in debug.coffee")
	}
	return
}

// ---------------------------------------------------------------------------

export const dumpFuncList = () => {

	console.log('lFuncList: --------------------------------')
	console.log(toNice(lFuncList))
	console.log('-------------------------------------------')
	return
}

// ---------------------------------------------------------------------------

export const dumpLoggers = (label = undef): void => {

	const lLines: string[] = []
	if (nonEmpty(label)) {
		lLines.push(`LOGGERS (${label})`)
	}
	else {
		lLines.push("LOGGERS")
	}
	lLines.push(`   enter      - ${logType(logEnter, stdEnter)}`)
	lLines.push(`   return     - ${logType(logReturn, stdReturn)}`)
	lLines.push(`   yield      - ${logType(logYield, stdYield)}`)
	lLines.push(`   resume     - ${logType(logResume, stdResume)}`)
	lLines.push(`   value      - ${logType(logValue, stdLogValue)}`)
	console.log(arrayToBlock(lLines))
	return
}

// ---------------------------------------------------------------------------

const logType = (
		cur: TLogFunc,
		std: TLogFunc
		): string => {

	if (cur === std) {
		return 'std'
	}
	else if (defined(cur)) {
		return 'custom'
	}
	else {
		return 'undef'
	}
}

// ---------------------------------------------------------------------------

export var LOGVALUE = (
		label: string,
		value: unknown,
		hOptions: hash = {}
		): void => {

	// --- Allow label to be empty, i.e. ''

	type opt = {
		prefix: string
		short: boolean
		oneIndent: string
		}
	const {prefix, short, oneIndent} = getOptions<opt>(hOptions, {
		prefix: '',
		short: false,      // prefer short strings, e.g. 'HASH', 'ARRAY'
		oneIndent: '\t'
		})

	if (internalDebugging) {
		const str1 = OL(label)
		const str2 = OL(value)
		const str3 = OL(prefix)
		console.log(`CALL LOGVALUE(${str1}, ${str2}), prefix=${str3}`)
	}

	const labelStr = defined(label) ? `${label} = ` : ''

	const jsTyp = jsType(value)

	// --- Handle certain values which should fit, unless
	//     indentation is very deep, but we'll keep it on one line
	//     in any case

	const olStr = `${prefix}${labelStr}${OL(value)}`
	if (isShortVal(jsTyp) || stringFits(olStr)) {
		if (internalDebugging) {
			console.log(`Using OL(), ${olStr.length} <= ${logWidth}`)
		}
		LOG(olStr)
		return
	}

	if (short) {
		if (jsTyp === 'array') {
			LOG(`${prefix}${labelStr}ARRAY`)
			return
		}
		if (jsTyp === 'hash') {
			LOG(`${prefix}${labelStr}HASH`)
			return
		}
		if (jsTyp === 'function') {
			LOG(`${prefix}${labelStr}FUNCTION`)
			return
		}
	}

	const itemPrefix = prefix + oneIndent

	// --- We know now that OL(value) doesn't fit
	//     and all "short values" have been checked already
	switch(jsTyp) {
		case 'string': {
			obviously((typeof value === 'string'))
			LOG(`${prefix}${labelStr}\"\"\"`)
			for (const line of blockToArray(value)) {
				LOG(`${itemPrefix}${line}\n			LOG `)
			};break;
		}//{itemPrefix}\"\"\""

		case 'hash': {
			const str = toNice(value, {
				sortKeys: true,
				oneIndent: spaces(3)
				})
			if (labelStr) {
				LOG(`${prefix}${labelStr}`)
			}
			for (const s in blockToArray(str)) {
				LOG(`${itemPrefix}${s}`)
			};break;
		}

		case 'array': {
			const str = toNice(value, {
				sortKeys: true,
				oneIndent: spaces(3)
				})
			if (labelStr) {
				LOG(`${prefix}${labelStr}`)
			}
			for (const s in blockToArray(str)) {
				LOG(`${itemPrefix}${s}`)
			};break;
		}

		case 'function': {
			LOG(`${prefix}${labelStr}<function>`);break;
		}

		case 'object': {
			const str = toNice(value)
			if (str.includes("\n")) {
				if (labelStr) {
					LOG(`${prefix}${labelStr}`)
				}
				for (const line in blockToArray(str)) {
					LOG(`${itemPrefix}${line}`)
				}
			}
			else {
				LOG(`${prefix}${labelStr}${str}`)
			};break;
		}
	}
	return
}

// ---------------------------------------------------------------------------

const isShortVal = (typ: string) => {

	return words('undef null boolean integer float bigint symbol',
	             'NaN inf neginf null regexp').includes(typ)
}

// ---------------------------------------------------------------------------

export const shortStr = (
		value: unknown,
		typ: string = jsType(value),
		maxLen: number = 32
		): string => {

	if (isShortVal(typ)) {
		return OL(value)
	}
	switch(typ) {
		case 'string': {
			obviously((typeof value === 'string'))
			const len = value.length
			return (
				  (len <= maxLen)
				? value
				: value.substring(0, len - 3) + '...'
				)
		}

		case 'hash': { return 'HASH'
		}
		case 'array': { return 'ARRAY'
		}
		case 'set': { return 'SET'
		}
		case 'map': { return 'MAP'
		}
		case 'iterator': { return 'ITERATOR'
		}
		case 'asyncIterator': { return 'ASYNC ITERATOR'
		}
		case 'class': { return 'CLASS'
		}
		case 'generator': { return 'GENERATOR'
		}
		case 'asyncGenerator': { return 'ASYNC GENERATOR'
		}
		case 'plainFunction': { return 'FUNCTION'
		}
		default: { croak(`Unknown value type: ${OL(value)}`) }
	}
}

